#' Treatment Effects
#'
#' 
#' @param data .
#' @param outcome .
#' @param treat .
#' @param control .
#' @param covs .
#' @param block .
#' @param cluster .
#' @param method .
#' @param se .
#' @param level .
#' @param showHelp .
#' @param showGuide .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$guide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$helpText} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$notes} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$desc} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$est} \tab \tab \tab \tab \tab a table \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$desc$asDF}
#'
#' \code{as.data.frame(results$desc)}
#'
#' @export
exeffect <- function(
    data,
    outcome,
    treat,
    control = "",
    covs,
    block,
    cluster,
    method = "diff",
    se = "auto",
    level = 95,
    showHelp = FALSE,
    showGuide = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("exeffect requires jmvcore to be installed (restart may be required)")

    if ( ! missing(outcome)) outcome <- jmvcore::resolveQuo(jmvcore::enquo(outcome))
    if ( ! missing(treat)) treat <- jmvcore::resolveQuo(jmvcore::enquo(treat))
    if ( ! missing(covs)) covs <- jmvcore::resolveQuo(jmvcore::enquo(covs))
    if ( ! missing(block)) block <- jmvcore::resolveQuo(jmvcore::enquo(block))
    if ( ! missing(cluster)) cluster <- jmvcore::resolveQuo(jmvcore::enquo(cluster))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(outcome), outcome, NULL),
            `if`( ! missing(treat), treat, NULL),
            `if`( ! missing(covs), covs, NULL),
            `if`( ! missing(block), block, NULL),
            `if`( ! missing(cluster), cluster, NULL))


    options <- exeffectOptions$new(
        outcome = outcome,
        treat = treat,
        control = control,
        covs = covs,
        block = block,
        cluster = cluster,
        method = method,
        se = se,
        level = level,
        showHelp = showHelp,
        showGuide = showGuide)

    analysis <- exeffectClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

